import { MigrateDownArgs, MigrateUpArgs, sql } from '@payloadcms/db-postgres'

import {
  mediaFilesTableStatements,
  mediaStorageColumnStatements,
} from '../lib/media-storage-schema'

/**
 * Media storage schema.
 *
 * The column statements were generated by `payload migrate:create media_storage` — Payload adds
 * `prefix` / `_objectkey` to the `media` collection whenever a storage adapter is active (Vercel
 * Blob *or* the Postgres fallback), and without those columns every media read and write fails
 * with a Postgres error. The `media_files` table is the Postgres media store itself; it lives
 * outside Payload's own schema (the adapter addresses it with raw SQL), so it is created here and
 * on boot — see `src/lib/media-storage-schema.ts`, which both paths share.
 *
 * Everything is `IF NOT EXISTS`: the application also prepares the schema when it boots, so a
 * database that already has these objects (a development `push`, an earlier deployment of the same
 * code, a re-run after a partial failure) must not fail the migration.
 */
export async function up({ db }: MigrateUpArgs): Promise<void> {
  for (const statement of [...mediaStorageColumnStatements, ...mediaFilesTableStatements]) {
    await db.execute(sql.raw(statement))
  }
}

export async function down({ db }: MigrateDownArgs): Promise<void> {
  await db.execute(sql`ALTER TABLE "media" DROP COLUMN IF EXISTS "_objectkey";`)
  await db.execute(sql`ALTER TABLE "media" DROP COLUMN IF EXISTS "prefix";`)
  // `media_files` is intentionally left behind: rolling a migration back must never destroy bytes
  // that editors uploaded. Drop it by hand if the storage fallback is being removed for good.
}
